class Obligation extends DataClass implements Insertable<Obligation> {
  final String id;
  final String userId;
  final String concept;
  final String categoryId;
  final String? accountId;
  final ObligationType type;
  final ObligationFrequency frequency;
  final int amountPerPeriod;

  /// Día del mes (1-31) en que se paga. Para frecuencia `semanal` se
  /// interpreta como día ISO de la semana (1=lunes..7=domingo). Para
  /// `anual` se ignora: se usa el mes/día de `start_date` como aniversario.
  final int? paymentDay;
  final ObligationStatus status;
  final DateTime? lastGeneratedDate;
  final int? totalAmount;
  final DateTime? startDate;
  final DateTime? endDate;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  const Obligation({
    required this.id,
    required this.userId,
    required this.concept,
    required this.categoryId,
    this.accountId,
    required this.type,
    required this.frequency,
    required this.amountPerPeriod,
    this.paymentDay,
    required this.status,
    this.lastGeneratedDate,
    this.totalAmount,
    this.startDate,
    this.endDate,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
  });
