    map['category_id'] = Variable<String>(categoryId);
    if (!nullToAbsent || accountId != null) {
      map['account_id'] = Variable<String>(accountId);
    }
    {
      map['type'] = Variable<String>(
        $ObligationsTable.$convertertype.toSql(type),
      );
    }
    {
      map['frequency'] = Variable<String>(
        $ObligationsTable.$converterfrequency.toSql(frequency),
      );
    }
    map['amount_per_period'] = Variable<int>(amountPerPeriod);
    if (!nullToAbsent || paymentDay != null) {
      map['payment_day'] = Variable<int>(paymentDay);
    }
    {
      map['status'] = Variable<String>(
        $ObligationsTable.$converterstatus.toSql(status),
      );
    }
    if (!nullToAbsent || lastGeneratedDate != null) {
      map['last_generated_date'] = Variable<DateTime>(lastGeneratedDate);
    }
    if (!nullToAbsent || totalAmount != null) {
      map['total_amount'] = Variable<int>(totalAmount);
    }
    if (!nullToAbsent || startDate != null) {
      map['start_date'] = Variable<DateTime>(startDate);
    }
    if (!nullToAbsent || endDate != null) {
